<script lang="ts">
  import { onMount } from 'svelte';
  import { api } from '$lib/api/client';
  import type { Experiment } from '$lib/types/api';
  import StatePanel from '$lib/components/StatePanel.svelte';
  import { formatTime } from '$lib/utils/format';
  let items: Experiment[] = [], loading = true, error = '';
  $: running = items.filter((item) => item.status === 'running').length;
  $: completed = items.filter((item) => item.status === 'completed').length;
  $: failed = items.filter((item) => item.status === 'failed').length;
  async function load() { loading = true; error = ''; try { items = await api.experiments(); } catch (e) { error = e instanceof Error ? e.message : 'Unable to load experiments'; } finally { loading = false; } }
  onMount(load);
</script>

<svelte:head><title>Experiments · Temporal RCA</title></svelte:head>

<div class="page-heading"><div><span class="eyebrow">Ground truth archive</span><h1 class="display">Experiments</h1><p>Reproducible fault windows, linked telemetry and exportable evidence.</p></div><button class="button" on:click={load} disabled={loading}>↻ Refresh runs</button></div>

{#if loading}<StatePanel state="loading" title="Loading experiment runs…" />{:else if error}<StatePanel state="error" message={error} retry={load} />{:else}
  <div class="stat-grid"><div class="stat-card"><span class="stat-icon">∑</span><div><span class="eyebrow">Total runs</span><strong>{items.length}</strong><small>Ground-truth records</small></div></div><div class="stat-card"><span class="stat-icon live">●</span><div><span class="eyebrow">In progress</span><strong>{running}</strong><small>{running ? 'Capturing live evidence' : 'No active runs'}</small></div></div><div class="stat-card"><span class="stat-icon good">✓</span><div><span class="eyebrow">Completed</span><strong>{completed}</strong><small>Ready to correlate</small></div></div><div class="stat-card"><span class="stat-icon bad">!</span><div><span class="eyebrow">Failed</span><strong>{failed}</strong><small>{failed ? 'Review the run details' : 'No failed runs'}</small></div></div></div>
  {#if !items.length}<StatePanel state="empty" title="No experiments recorded" message="Run an allowlisted scenario to mark ground truth on the timeline." />{:else}<section class="runs panel"><header class="runs-header"><div><span class="eyebrow">Run history</span><strong>Evidence capture sessions</strong></div><span class="mono count">{items.length} runs</span></header><div class="run-list">{#each items as item (item.id)}<a class="run" href={`/experiments/${item.id}`}><span class="run-mark" class:running={item.status === 'running'} class:failed={item.status === 'failed'} aria-hidden="true">{item.status === 'failed' ? '◆' : item.status === 'running' ? '●' : '◇'}</span><div class="run-name"><span class="eyebrow">{item.scenario || 'experiment'} <i>/</i> {item.id.slice(0, 8)}</span><h2>{item.name}</h2></div><span class="status" class:status-running={item.status === 'running'} class:status-failed={item.status === 'failed'}>{item.status}</span><time class="mono">{item.started_at ? formatTime(item.started_at) : 'Not started'}</time><span class="arrow" aria-hidden="true">→</span></a>{/each}</div></section>{/if}
{/if}

<style>
  .page-heading { display:flex; align-items:end; justify-content:space-between; gap:20px; margin-bottom:19px; }.page-heading h1 { margin:5px 0 4px; font-size:40px; }.page-heading p { margin:0; color:var(--muted); font-size:13px; }.page-heading .button { min-height:34px; font-size:11px; }
  .stat-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:9px; margin-bottom:11px; }.stat-card { min-width:0; display:flex; align-items:center; gap:10px; padding:13px; border:1px solid var(--line); border-radius:7px; background:linear-gradient(135deg,rgba(32,32,32,.88),rgba(10,10,10,.93)); }.stat-card>div { min-width:0; display:flex; flex-direction:column; gap:3px; }.stat-card strong { font:600 24px 'IBM Plex Mono',monospace; color:var(--text); }.stat-card small { color:#8f8f8f; font:9px 'IBM Plex Mono',monospace; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }.stat-icon { width:27px; height:27px; display:grid; place-items:center; flex:0 0 27px; border-radius:6px; color:var(--brand-300); background:var(--brand-soft); font:14px 'IBM Plex Mono',monospace; }.stat-icon.live { color:var(--cyan); background:var(--cyan-soft); }.stat-icon.good { color:var(--success); background:var(--success-soft); }.stat-icon.bad { color:var(--coral); background:var(--danger-soft); }
  .runs { overflow:hidden; }.runs-header { min-height:57px; display:flex; align-items:center; justify-content:space-between; padding:10px 14px; border-bottom:1px solid var(--line); }.runs-header>div { display:flex; flex-direction:column; gap:4px; }.runs-header strong { font-size:12px; }.count { color:#728292; font-size:10px; }.run { display:grid; grid-template-columns:20px minmax(0,1fr) 92px 105px 22px; align-items:center; gap:10px; min-height:68px; padding:9px 14px; color:var(--text); text-decoration:none; border-bottom:1px solid var(--line); }.run:last-child { border-bottom:0; }.run:hover { background:var(--surface-hover); }.run-mark { color:var(--brand-300); font-size:13px; }.run-mark.running { color:var(--cyan); }.run-mark.failed { color:var(--coral); }.run-name { min-width:0; }.run-name .eyebrow { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:9px; }.run-name i { color:#596672; font-style:normal; }.run h2 { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; margin:5px 0 0; font-size:13px; font-weight:600; }.status { color:#a3a3a3; font:10px 'IBM Plex Mono',monospace; text-transform:uppercase; }.status-running { color:var(--cyan); }.status-failed { color:var(--coral); }.run time { color:#a3a3a3; font-size:10px; }.arrow { color:var(--muted); text-align:right; }.run:hover .arrow { color:var(--brand-300); }
  @media (max-width:850px) { .stat-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } } @media (max-width:600px) { .page-heading { align-items:flex-start; }.page-heading h1 { font-size:34px; }.page-heading p { max-width:36ch; line-height:1.45; }.stat-grid { gap:7px; }.stat-card { padding:10px; }.run { grid-template-columns:18px minmax(0,1fr) 20px; gap:8px; padding:9px 10px; }.run .status,.run time { display:none; }.run-name .eyebrow { font-size:8px; } }
</style>
